{
  "judgments": [
    {
      "issue_id": "region.f0f05e7705d84fc097657601",
      "disposition": "VISIBLE_MISSING_OR_CHANGED_TEXT",
      "printed_text": "5. The past performance information presented is not indicative of future performance.",
      "explanation": "The printed warning visibly begins with “5.”. The reported deletion omits that numbered label; it is not a spacing or hyphenation difference. The warning's wording is unchanged by the listed deletion.",
      "affected_condition": "Numbering of the warning about past performance."
    },
    {
      "issue_id": "region.76da7dcc5d70d5d02b049007",
      "disposition": "VISIBLE_MISSING_OR_CHANGED_TEXT",
      "printed_text": "6. The 1-day annualised yield, 7-day annualised yield and the 30-day annualised yield are based on 1-day period, 7-day period and 30-day period of XXX Money Market Fund’s past performance respectively and do not represent an actual one-year yield.",
      "explanation": "The printed paragraph visibly begins with “6.”. The reported deletion removes its numbered label. This is an omission of printed text, although the listed deletion does not alter the periods or the qualification about an actual one-year yield.",
      "affected_condition": "Numbering of the warning distinguishing annualised short-period performance from an actual one-year yield."
    },
    {
      "issue_id": "region.71683d731018bdf3114aea8a",
      "disposition": "VISIBLE_TYPOGRAPHIC_DIFFERENCE",
      "printed_text": "7-day annualised yield",
      "explanation": "In warning 6, the page prints “7-day annualised yield” with a hyphen joining the numeral and “day”. The tokens “7-”, “day” and the single token “7-day” represent the same visible expression. No numeral, unit or qualifying word is changed. The other supplied locations likewise show the hyphenated expression.",
      "affected_condition": "The seven-day period used for the annualised yield."
    },
    {
      "issue_id": "region.9a8bb6e36a9b8764ee4a5878",
      "disposition": "VISIBLE_TYPOGRAPHIC_DIFFERENCE",
      "printed_text": "30-day annualised yield",
      "explanation": "Warning 6 visibly prints “30-day annualised yield”. Splitting it into “30” and “-day” rather than one token is a typographic or tokenisation difference, without a changed duration. The supplied location in the bottom notes is a separate occurrence in “30 Aug 2023”; that date is not an occurrence of “30-day”.",
      "affected_condition": "The thirty-day period used for the annualised yield."
    },
    {
      "issue_id": "region.ce3e809d1bedde5b6b907ee3",
      "disposition": "VISIBLE_TYPOGRAPHIC_DIFFERENCE",
      "printed_text": "are based on 1-day period, 7-day period and 30-day period",
      "explanation": "Warning 6 prints “1-day” within the statement of the underlying performance periods. The tokens “1-”, “day” preserve the numeral, hyphen and unit printed together as “1-day”. No duration or qualification is omitted by this difference.",
      "affected_condition": "The one-day performance period underlying the corresponding annualised yield."
    },
    {
      "issue_id": "region.d8c4f8b5dcd5511d09f5ab19",
      "disposition": "VISIBLE_TYPOGRAPHIC_DIFFERENCE",
      "printed_text": "are based on 1-day period, 7-day period and 30-day period",
      "explanation": "The printed period is “7-day”. Separating “7” from “-day” in the token sequence does not change the visible numeral, hyphen or unit. The association of this period with the corresponding annualised yield remains expressed by “respectively” later in the warning.",
      "affected_condition": "The seven-day performance period underlying the corresponding annualised yield."
    },
    {
      "issue_id": "region.2459e8accf62c63511a57132",
      "disposition": "VISIBLE_TYPOGRAPHIC_DIFFERENCE",
      "printed_text": "are based on 1-day period, 7-day period and 30-day period",
      "explanation": "Warning 6 visibly gives “30-day period”. The split tokens “30”, “-day” and the joined token “30-day” preserve the same printed duration. The additional supplied location showing “30” in the bottom notes belongs to the date “30 Aug 2023” and should not be conflated with this duration.",
      "affected_condition": "The thirty-day performance period underlying the corresponding annualised yield."
    },
    {
      "issue_id": "region.43041249dd4b8b44c4da0e36",
      "disposition": "VISIBLE_TYPOGRAPHIC_DIFFERENCE",
      "printed_text": "XXX Money Market Fund’s past performance",
      "explanation": "The page uses a curved apostrophe in “Fund’s”. Replacing it with the straight apostrophe in “Fund's” changes punctuation typography while retaining the possessive wording and its reference to the fund's past performance.",
      "affected_condition": null
    },
    {
      "issue_id": "region.1420678018572c761e9bbb24",
      "disposition": "VISIBLE_MISSING_OR_CHANGED_TEXT",
      "printed_text": "7. The assumptions involved in the calculation of the 1-day annualised yield, 7-day annualised yield and the 30-day annualised yield are hypothetical.",
      "explanation": "The printed warning visibly begins with “7.”. The reported deletion omits this numbered label. It does not, by itself, remove or modify the statement that the calculation assumptions are hypothetical.",
      "affected_condition": "Numbering of the warning about hypothetical calculation assumptions."
    },
    {
      "issue_id": "region.a5ad42c2c28896601e666f6f",
      "disposition": "VISIBLE_TYPOGRAPHIC_DIFFERENCE",
      "printed_text": "the calculation of the 1-day annualised yield",
      "explanation": "Warning 7 prints the hyphenated expression “1-day”. The extraction difference joins “1-” and “day” without changing the numeral, unit or surrounding qualification that the calculation assumptions are hypothetical.",
      "affected_condition": "Inclusion of the one-day annualised yield in the warning about hypothetical assumptions."
    },
    {
      "issue_id": "region.c8f201fd96c8e54428168f6f",
      "disposition": "VISIBLE_TYPOGRAPHIC_DIFFERENCE",
      "printed_text": "7-day annualised yield",
      "explanation": "In warning 7, “7-day” is visible at the end of a line and “annualised yield” continues on the following line. The reported change from “7-”, “day” to “7-day” concerns token separation within the hyphenated duration. It does not change the duration or its inclusion in the hypothetical-assumptions warning.",
      "affected_condition": "Inclusion of the seven-day annualised yield in the warning about hypothetical assumptions."
    },
    {
      "issue_id": "region.44496012316eba8d0ada312f",
      "disposition": "VISIBLE_TYPOGRAPHIC_DIFFERENCE",
      "printed_text": "•",
      "explanation": "Solid round bullets are visible at all six supplied locations: two precede placeholder lines below the fund title, and four precede the computation-basis descriptions. The reported deletion omits a visible list marker, which is a list-formatting difference; it does not itself delete a word, yield value, period or calculation qualification. The supplied locations do not uniquely identify which bullet the single deletion concerns. These bullets are distinct from the asterisk linking the yield headings to “Computation basis and periods covered” and the superscript “#” linking the one-day yield figure to the daily-figure footnote.",
      "affected_condition": "Visual marking of a list item; the particular item affected is not uniquely identified by the supplied locations."
    }
  ],
  "remaining_questions": [
    "Which of the six supplied bullet locations corresponds to the single deletion in region.44496012316eba8d0ada312f? The bullets are legible, but the location list does not uniquely resolve that correspondence."
  ]
}
